/* ===================================
   CDS Website - Counters
   File: counters.js
   Purpose: Counter animations for statistics
   =================================== */

// ===================================
// Counter Animation
// ===================================
function initCounters() {
    const counters = document.querySelectorAll('.stat-number[data-count]');

    const observerOptions = {
        threshold: 0.5,
        rootMargin: '0px'
    };

    const observer = new IntersectionObserver(function (entries) {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                animateCounter(entry.target);
                observer.unobserve(entry.target);
            }
        });
    }, observerOptions);

    counters.forEach(counter => observer.observe(counter));
}

function animateCounter(element) {
    const target = parseInt(element.getAttribute('data-count'));
    const duration = 2000; // 2 seconds
    const increment = target / (duration / 16); // 60fps
    let current = 0;

    const timer = setInterval(function () {
        current += increment;
        if (current >= target) {
            element.textContent = formatNumber(target);
            clearInterval(timer);
        } else {
            element.textContent = formatNumber(Math.floor(current));
        }
    }, 16);
}

function formatNumber(num) {
    if (num >= 1000) {
        return (num / 1000).toFixed(1) + 'K+';
    }
    return num + '+';
}
/**
 * FAQ Toggle Function
 * Handles the 'Sleek Card' accordion behavior.
 * Triggered via onclick="toggleFaq(this)" in HTML.
 */
function toggleFaq(element) {
    // Close other items
    const allItems = document.querySelectorAll('.faq-item-card');
    allItems.forEach(item => {
        if (item !== element) {
            item.classList.remove('active');
            // Reset max-height for others if we were using JS (but we use CSS)
        }
    });

    // Toggle clicked item
    element.classList.toggle('active');
}
